package com.example.standup;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity {
 TextView countdown; Button toggle; Handler handler=new Handler();
 Runnable update=new Runnable(){public void run(){long end=getSharedPreferences("timer",0).getLong("end",0);boolean active=getSharedPreferences("timer",0).getBoolean("active",false);long ms=Math.max(0,end-System.currentTimeMillis());countdown.setText(active?String.format(java.util.Locale.US,"%02d:%02d",ms/60000,(ms/1000)%60):"20:00");toggle.setText(active?"Stop reminders":"Start reminders");handler.postDelayed(this,500);}};
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(17,24,39));LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setGravity(Gravity.CENTER);l.setPadding(35,35,35,35);l.setBackgroundColor(Color.rgb(17,24,39));TextView title=new TextView(this);title.setText("STAND UP REMINDER");title.setTextSize(24);title.setTextColor(-1);title.setGravity(Gravity.CENTER);l.addView(title);countdown=new TextView(this);countdown.setTextSize(65);countdown.setTextColor(Color.rgb(74,222,128));countdown.setGravity(Gravity.CENTER);l.addView(countdown);TextView info=new TextView(this);info.setText("A gentle reminder to stand and move every 20 minutes.");info.setTextColor(-1);info.setTextSize(16);info.setGravity(Gravity.CENTER);l.addView(info);toggle=new Button(this);l.addView(toggle);toggle.setOnClickListener(v->{boolean active=getSharedPreferences("timer",0).getBoolean("active",false);Intent i=new Intent(this,ReminderService.class);i.setAction(active?"STOP":"START");if(active)startService(i);else startForegroundService(i);});setContentView(l);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=getPackageManager().PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);handler.post(update);}
 public void onDestroy(){handler.removeCallbacks(update);super.onDestroy();}
}
